'use strict';
/*
 * extract.config.js - t02-chinese-alias
 * Pattern: "Chinese-name-reference library" (references/extraction-config.md)
 *   - entities keyed by stable slug ids, each carrying a Chinese display name
 *   - relations reference entities by DISPLAY NAME, not id
 *   - buildPack converts name refs -> ids and emits an aliases table (name -> id)
 */
const path = require('path');

const libDir = __dirname; // cwd == input (parent of lib/)

module.exports = {
  libId: 'family-tree',
  libDir: libDir,
  engineFile: 'lib/src/family-tree.js',
  globalName: 'FamilyTree',
  schemaVersion: '1.2',

  // 1. Slice the two embedded default-data literals out of the engine.
  literals: [
    { key: 'chars', pattern: /var chars = \(options && options\.chars\) \|\|/ },
    { key: 'edges', pattern: /var edges = \(options && options\.edges\) \|\|/ }
  ],

  meta: {
    title: '家族关系图',
    hero: 'zhangsan',
    source: 'engine-embedded-defaults'
  },

  // 2. Build a spec-compliant Data Pack from the sliced defaults.
  buildPack(defaults) {
    const chars = defaults.chars; // { zhangsan: {name,kind,title}, ... }
    const edges = defaults.edges; // [{ a:'张三', b:'李四', type, label }, ...]

    // display-name -> stable id (the aliases table; inverse lets us convert edges)
    const nameToId = {};
    Object.keys(chars).forEach(function (id) {
      nameToId[chars[id].name] = id;
    });

    return {
      meta: {
        title: '家族关系图',
        hero: 'zhangsan',
        source: 'engine-embedded-defaults'
      },
      // entities keyed by stable id; preserve business fields (name/kind/title)
      entities: chars,
      // aliases: each display name -> id  (so E4/E5 pass)
      aliases: nameToId,
      // relation-type registry (E6)
      relationTypes: {
        family: { label: '同族', color: '#8a8a8a' },
        marriage: { label: '联姻', color: '#c0392b' }
      },
      // master edge list with a/b converted from names -> ids (E5)
      relations: edges.map(function (e) {
        const r = {
          a: nameToId[e.a] || e.a,
          b: nameToId[e.b] || e.b,
          type: e.type
        };
        if (e.label !== undefined) r.label = e.label;
        return r;
      })
    };
  },

  // 3. Equivalence: __fromPack(pack) must deep-equal the embedded defaults.
  //    Engine returns { chars, allEdges }; defaults are { chars, edges }.
  equivalence: [
    { lit: 'chars', from: 'chars' },
    { lit: 'edges', from: 'allEdges' }
  ]
};

'use strict';
/*
 * family-tree.js - Chinese-name-reference character engine (synthetic t02 fixture)
 *
 * Entities use Chinese names as keys (no stable ids); relations reference by name.
 * This is the "Chinese-name-reference library" pattern from extraction-config.md:
 * the model must convert names to stable ids via a hand-written idMap, then build
 * an aliases table mapping display names -> ids. E5/E7 explode if names aren't
 * normalized.
 */
var FamilyTree = (function () {
  var options = (typeof options !== 'undefined') ? options : undefined;
  var chars = (options && options.chars) || {
    zhangsan: { name: '张三', kind: 'person', title: '家主' },
    lisi: { name: '李四', kind: 'person', title: '族弟' },
    wangwu: { name: '王五', kind: 'person', title: '姻亲' }
  };
  var edges = (options && options.edges) || [
    { a: '张三', b: '李四', type: 'family', label: '同族' },
    { a: '张三', b: '王五', type: 'marriage', label: '联姻' }
  ];

  function mount(root, options) {
    var c = (options && options.chars) || chars;
    var e = (options && options.edges) || edges;
    return { chars: c, edges: e };
  }

  // Reconstruct engine defaults from a Data Pack (equivalence-test hook).
  // IMPORTANT: the engine's native keys are Chinese names, NOT ids. So fromPack
  // must map id-based entities/relations back to name-based form.
  function __fromPack(pack) {
    var p = pack || {};
    var idToName = {};
    var restoredChars = {};
    Object.keys(p.entities || {}).forEach(function (id) {
      var ent = p.entities[id];
      var name = ent.name;
      idToName[id] = name;
      restoredChars[id] = { name: name, kind: ent.kind };
      if (ent.title) restoredChars[id].title = ent.title;
    });
    var restoredEdges = (p.relations || []).map(function (r) {
      var edge = { a: idToName[r.a] || r.a, b: idToName[r.b] || r.b, type: r.type };
      if (r.label) edge.label = r.label;
      return edge;
    });
    return { chars: restoredChars, allEdges: restoredEdges };
  }

  return { mount: mount, __fromPack: __fromPack };
})();

if (typeof globalThis !== 'undefined') globalThis.FamilyTree = FamilyTree;

'use strict';
/*
 * SG Data Pack extraction config - t02 Chinese-name-reference library (Pattern B)
 *
 * Source engine (lib/src/family-tree.js):
 *   - chars keyed by stable id (zhangsan/lisi/wangwu), each carrying a Chinese `name`
 *   - edges reference entities by DISPLAY NAME (张三/李四/王五), not by id
 *
 * Conversion: build an idMap (name -> id) from chars, convert edges.a/b to ids,
 * and emit an aliases table (name -> id) so E4/E5 pass.
 */

const LIB_DIR = '/Users/tangyaoyue/DEV/tool-self-harness/tasks/held-in/t02-chinese-alias/input';

module.exports = {
  libId: 't02-chinese-alias',
  libDir: LIB_DIR,
  engineFile: 'lib/src/family-tree.js',
  globalName: 'FamilyTree',

  // Slice both default-data literals. Pattern ends at the trailing `||` (expression start).
  literals: [
    { key: 'chars', pattern: /var chars = \(options && options\.chars\) \|\|/ },
    { key: 'edges', pattern: /var edges = \(options && options\.edges\) \|\|/ }
  ],

  meta: {
    title: '家族关系图 (Chinese-name-reference)',
    hero: 'zhangsan',
    source: 'Embedded data from original case page (decomposition export)',
    fetchedAt: new Date().toISOString().slice(0, 10)
  },

  buildPack(defaults) {
    const chars = defaults.chars || {};
    const edges = defaults.edges || [];

    // name -> id map (the core of the Chinese-name-reference conversion)
    const idMap = {};
    for (const [id, c] of Object.entries(chars)) idMap[c.name] = id;

    // ① Entity table: stable id keys, preserve name/kind + all business fields (title, ...)
    const entities = {};
    for (const [id, c] of Object.entries(chars)) {
      entities[id] = Object.assign({}, c); // keeps name, kind, title
    }

    // ② Alias table: display name -> id (crawl-normalization entry point; satisfies E4/E5)
    const aliases = {};
    for (const [id, c] of Object.entries(chars)) aliases[c.name] = id;

    // ③ Relationship-type registry (every relations[].type must be registered -> E6)
    const relationTypes = {
      family: { label: '同族', color: '#d94b4b' },
      marriage: { label: '联姻', color: '#4b7bd9' }
    };

    // ④ Master edge list: convert display-name refs -> ids (a/b are ids, not names)
    const relations = edges.map((e) => {
      const rel = {
        a: idMap[e.a] || e.a,
        b: idMap[e.b] || e.b,
        type: e.type
      };
      if (e.label) rel.label = e.label;
      return rel;
    });

    const pack = {
      entities,
      aliases,
      relationTypes,
      relations,
      domain: {}
    };

    // ⑤ Provenance stamping (mandatory in v1.2; generic stamp, never hand-written)
    const stamp = (origin) => ({
      origin,
      sourceUrl: null,
      fetchedAt: new Date().toISOString().slice(0, 10),
      confidence: 1.0,
      note: 'Baseline data (embedded in original case page); original sourceUrl lost'
    });
    pack.provenance = {
      entities: Object.fromEntries(
        Object.keys(pack.entities).map((id) => [id, stamp('engine-embedded-defaults')])
      ),
      relations: Object.fromEntries(
        pack.relations.map((r) => [r.a + '::' + r.b, stamp('engine-embedded-defaults')])
      )
    };

    return pack;
  },

  // Losslessness check: fromPack(pack)[from] deep-equals defaults[lit]
  // __fromPack returns { chars (id-keyed, name/kind/title), allEdges (name-based a/b) }
  equivalence: [
    { lit: 'chars', from: 'chars' },
    { lit: 'edges', from: 'allEdges' }
  ],

  domainSchema: {
    type: 'object',
    description: 'Library-specific data collections',
    additionalProperties: true
  }
};

